@pytest.mark.parametrize(("type_", "codec", "expected"), CASES)
def test_column_codec_rules(type_: str, codec: Any, expected: tuple[str, str] | None) -> None:
    definition = table(
        database="app",
        name="events",
        engine="MergeTree()",
        primary_key=["id"],
        order_by=["id"],
        columns=[{"name": "id", "type": "UInt64"}, {"name": "c", "type": type_, "codec": codec}],
    )
    issues = [(issue.code, issue.message) for issue in validate_definitions([definition])]
    assert issues == (
        [(expected[0], f'Table app.events column "c" {expected[1]}')] if expected else []
    )
